import gget
import pandas as pd

sequence = ""

pd.set_option('display.max_columns', None)
ortholog_df, regex_df = gget.elm(sequence, uniprot=False, expand=True)
ortholog_df.to_csv("testing.csv", index=False)
regex_df.to_csv("testing_regex.csv", index=False)

# ortholog df contains info about DIAMOND alignment
# regex df contains ELM motifs matching in sequence

